-- Hair Clinic OS foundation. Apply to a fresh Supabase project only after reviewing.
create extension if not exists pgcrypto;
create schema if not exists private;

create type public.clinic_role as enum ('admin','reception','doctor','hair_team','finance');
create type public.appointment_kind as enum ('consultation','follow_up','mesotherapy','plasma','botox','cold_peel','skin_booster');
create type public.appointment_flow as enum ('booked','arrived','with_doctor','completed','cancelled','converted_to_operation');
create type public.operation_lab_status as enum ('pending','received');
create type public.money_direction as enum ('income','expense');
create type public.payment_method as enum ('cash','vodafone_cash','visa','instapay');

create table public.organizations (
  id uuid primary key default gen_random_uuid(), name text not null, created_at timestamptz not null default now()
);
create table public.branches (
  id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade,
  name text not null check (name in ('القاهرة','المنصورة')), created_at timestamptz not null default now(), unique(organization_id,name)
);
create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade, organization_id uuid not null references public.organizations(id) on delete cascade,
  full_name text not null, role public.clinic_role not null default 'reception', branch_id uuid references public.branches(id),
  permissions jsonb not null default '{}'::jsonb, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table public.patients (
  id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade,
  branch_id uuid not null references public.branches(id), patient_number bigint generated by default as identity,
  full_name text not null, age integer check(age between 0 and 125), phone text, national_id text, address text,
  acquisition_source text, notes text, created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique(organization_id, patient_number)
);
create index patients_org_branch_name_idx on public.patients(organization_id,branch_id,full_name);
create index patients_phone_idx on public.patients(organization_id,phone);
create table public.appointments (
  id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade,
  branch_id uuid not null references public.branches(id), patient_id uuid references public.patients(id) on delete set null,
  patient_name text not null, phone text, age integer check(age between 0 and 125), kind public.appointment_kind not null,
  scheduled_at timestamptz not null, fee numeric(12,2) not null default 0 check(fee>=0), service_mode text check(service_mode in ('paid','operation','manual_price')),
  arrival_source text, flow public.appointment_flow not null default 'booked', arrived_at timestamptz, doctor_entered_at timestamptz, completed_at timestamptz,
  notes text, created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index appointments_org_branch_time_idx on public.appointments(organization_id,branch_id,scheduled_at);
create table public.visits (
  id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade,
  branch_id uuid not null references public.branches(id), patient_id uuid not null references public.patients(id) on delete cascade,
  appointment_id uuid references public.appointments(id) on delete set null, doctor_id uuid references auth.users(id), visited_at timestamptz not null default now(),
  complaint text, diagnosis text, examination text, treatment_plan text, prescription text, notes text, created_by uuid references auth.users(id), created_at timestamptz not null default now()
);
create index visits_patient_date_idx on public.visits(patient_id,visited_at desc);
create table public.patient_images (
  id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade,
  branch_id uuid not null references public.branches(id), patient_id uuid not null references public.patients(id) on delete cascade,
  storage_path text not null unique, category text not null default 'clinical', captured_at timestamptz not null default now(), uploaded_by uuid references auth.users(id), watermark_applied boolean not null default false, notes text
);
create table public.operations (
  id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade,
  branch_id uuid not null references public.branches(id), patient_id uuid not null references public.patients(id) on delete restrict,
  scheduled_at timestamptz, national_id text, total_amount numeric(12,2) not null default 0 check(total_amount>=0), deposit_amount numeric(12,2) not null default 0 check(deposit_amount>=0),
  phone text, extractor_doctor_id uuid references public.profiles(id), opening_doctor_ids uuid[] not null default '{}', implant_doctor_name text,
  notes text, created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  check(deposit_amount<=total_amount)
);
create index operations_branch_schedule_idx on public.operations(organization_id,branch_id,scheduled_at);
create table public.operation_labs (
  id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade,
  branch_id uuid not null references public.branches(id), operation_id uuid not null references public.operations(id) on delete cascade,
  test_name text not null, status public.operation_lab_status not null default 'pending', received_at timestamptz, received_by uuid references auth.users(id), notes text
);
create table public.operation_team_assignments (
  id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade,
  branch_id uuid not null references public.branches(id), operation_id uuid not null references public.operations(id) on delete cascade,
  staff_profile_id uuid references public.profiles(id), team_role text not null check(team_role in ('extractor','opening','implant')), custom_name text, created_at timestamptz not null default now()
);
create table public.staff_schedules (
  id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade,
  branch_id uuid not null references public.branches(id), staff_profile_id uuid not null references public.profiles(id) on delete cascade,
  weekday smallint not null check(weekday between 0 and 6), start_time time not null, end_time time not null, active boolean not null default true, check(end_time>start_time), unique(staff_profile_id,weekday,start_time)
);
create table public.financial_transactions (
  id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade,
  branch_id uuid not null references public.branches(id), direction public.money_direction not null, description text not null,
  amount numeric(12,2) not null check(amount>0), payment_method public.payment_method not null, paid_at timestamptz not null default now(),
  patient_id uuid references public.patients(id), operation_id uuid references public.operations(id), created_by uuid references auth.users(id), created_at timestamptz not null default now()
);
create index finance_branch_date_idx on public.financial_transactions(organization_id,branch_id,paid_at);
create table public.audit_events (
  id bigint generated always as identity primary key, organization_id uuid not null references public.organizations(id) on delete cascade,
  branch_id uuid references public.branches(id), actor_id uuid references auth.users(id), event_type text not null, entity_table text not null, entity_id uuid, detail jsonb not null default '{}'::jsonb, created_at timestamptz not null default now()
);

-- Authorization helpers in a non-exposed schema. app role claims are not used; membership lives in profiles.
create or replace function private.current_profile()
returns public.profiles language sql stable security definer set search_path='' as $$
 select p from public.profiles p where p.id=(select auth.uid()) and p.active=true limit 1 $$;
create or replace function private.is_admin(org uuid)
returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.organization_id=org and p.active and p.role='admin') $$;
create or replace function private.can_access_branch(org uuid, branch uuid)
returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.organization_id=org and p.active and (p.role='admin' or p.branch_id=branch)) $$;
create or replace function private.can_read_patient_contact(org uuid, branch uuid)
returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.organization_id=org and p.active and (p.role in ('admin','reception') or (p.role='finance' and p.branch_id=branch))) $$;
revoke all on function private.current_profile() from public, anon;
revoke all on function private.is_admin(uuid) from public, anon;
revoke all on function private.can_access_branch(uuid,uuid) from public, anon;
revoke all on function private.can_read_patient_contact(uuid,uuid) from public, anon;
grant execute on function private.current_profile() to authenticated;
grant execute on function private.is_admin(uuid) to authenticated;
grant execute on function private.can_access_branch(uuid,uuid) to authenticated;
grant execute on function private.can_read_patient_contact(uuid,uuid) to authenticated;

-- Updated timestamp trigger
create or replace function private.touch_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now(); return new; end $$;
create trigger profiles_touch before update on public.profiles for each row execute function private.touch_updated_at();
create trigger patients_touch before update on public.patients for each row execute function private.touch_updated_at();
create trigger appointments_touch before update on public.appointments for each row execute function private.touch_updated_at();
create trigger operations_touch before update on public.operations for each row execute function private.touch_updated_at();

-- RLS for every exposed application table.
do $$ declare t text; begin
 foreach t in array['organizations','branches','profiles','patients','appointments','visits','patient_images','operations','operation_labs','operation_team_assignments','staff_schedules','financial_transactions','audit_events'] loop
  execute format('alter table public.%I enable row level security',t);
 end loop;
end $$;
-- Organizations and branches: members only; admins manage branch records.
create policy org_member_select on public.organizations for select to authenticated using (exists(select 1 from public.profiles p where p.organization_id=id and p.id=(select auth.uid()) and p.active));
create policy branches_select on public.branches for select to authenticated using (private.can_access_branch(organization_id,id));
create policy branches_admin_manage on public.branches for all to authenticated using (private.is_admin(organization_id)) with check(private.is_admin(organization_id));
-- Profile access: users can read own; admins manage organization users.
create policy profiles_self_or_admin_select on public.profiles for select to authenticated using (id=(select auth.uid()) or private.is_admin(organization_id));
create policy profiles_admin_insert on public.profiles for insert to authenticated with check(private.is_admin(organization_id));
create policy profiles_admin_update on public.profiles for update to authenticated using(private.is_admin(organization_id)) with check(private.is_admin(organization_id));
create policy profiles_admin_delete on public.profiles for delete to authenticated using(private.is_admin(organization_id));
-- Branch-scoped records. Contact fields are protected separately in application views; RLS branch isolates records.
create policy patients_select on public.patients for select to authenticated using(private.can_access_branch(organization_id,branch_id));
create policy patients_insert on public.patients for insert to authenticated with check(private.can_access_branch(organization_id,branch_id));
create policy patients_update on public.patients for update to authenticated using(private.can_access_branch(organization_id,branch_id)) with check(private.can_access_branch(organization_id,branch_id));
create policy patients_delete on public.patients for delete to authenticated using(private.is_admin(organization_id));
create policy appointments_select on public.appointments for select to authenticated using(private.can_access_branch(organization_id,branch_id));
create policy appointments_insert on public.appointments for insert to authenticated with check(private.can_access_branch(organization_id,branch_id));
create policy appointments_update on public.appointments for update to authenticated using(private.can_access_branch(organization_id,branch_id)) with check(private.can_access_branch(organization_id,branch_id));
create policy appointments_delete on public.appointments for delete to authenticated using(private.is_admin(organization_id));
create policy visits_select on public.visits for select to authenticated using(private.can_access_branch(organization_id,branch_id));
create policy visits_insert on public.visits for insert to authenticated with check(private.can_access_branch(organization_id,branch_id));
create policy visits_update on public.visits for update to authenticated using(private.can_access_branch(organization_id,branch_id)) with check(private.can_access_branch(organization_id,branch_id));
create policy visits_delete on public.visits for delete to authenticated using(private.is_admin(organization_id));
create policy patient_images_select on public.patient_images for select to authenticated using(private.can_access_branch(organization_id,branch_id));
create policy patient_images_insert on public.patient_images for insert to authenticated with check(private.can_access_branch(organization_id,branch_id));
create policy patient_images_update on public.patient_images for update to authenticated using(private.can_access_branch(organization_id,branch_id)) with check(private.can_access_branch(organization_id,branch_id));
create policy patient_images_delete on public.patient_images for delete to authenticated using(private.is_admin(organization_id));
create policy operations_select on public.operations for select to authenticated using(private.can_access_branch(organization_id,branch_id));
create policy operations_insert on public.operations for insert to authenticated with check(private.can_access_branch(organization_id,branch_id));
create policy operations_update on public.operations for update to authenticated using(private.can_access_branch(organization_id,branch_id)) with check(private.can_access_branch(organization_id,branch_id));
create policy operations_delete on public.operations for delete to authenticated using(private.is_admin(organization_id));
create policy labs_select on public.operation_labs for select to authenticated using(private.can_access_branch(organization_id,branch_id));
create policy labs_insert on public.operation_labs for insert to authenticated with check(private.can_access_branch(organization_id,branch_id));
create policy labs_update on public.operation_labs for update to authenticated using(private.can_access_branch(organization_id,branch_id)) with check(private.can_access_branch(organization_id,branch_id));
create policy labs_delete on public.operation_labs for delete to authenticated using(private.is_admin(organization_id));
create policy team_assignments_select on public.operation_team_assignments for select to authenticated using(private.can_access_branch(organization_id,branch_id));
create policy team_assignments_insert on public.operation_team_assignments for insert to authenticated with check(private.can_access_branch(organization_id,branch_id));
create policy team_assignments_update on public.operation_team_assignments for update to authenticated using(private.can_access_branch(organization_id,branch_id)) with check(private.can_access_branch(organization_id,branch_id));
create policy team_assignments_delete on public.operation_team_assignments for delete to authenticated using(private.is_admin(organization_id));
create policy schedules_select on public.staff_schedules for select to authenticated using(private.can_access_branch(organization_id,branch_id));
create policy schedules_insert on public.staff_schedules for insert to authenticated with check(private.can_access_branch(organization_id,branch_id));
create policy schedules_update on public.staff_schedules for update to authenticated using(private.can_access_branch(organization_id,branch_id)) with check(private.can_access_branch(organization_id,branch_id));
create policy schedules_delete on public.staff_schedules for delete to authenticated using(private.is_admin(organization_id));
create policy finance_select on public.financial_transactions for select to authenticated using(private.can_access_branch(organization_id,branch_id) and (private.is_admin(organization_id) or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='finance'));
create policy finance_insert on public.financial_transactions for insert to authenticated with check(private.can_access_branch(organization_id,branch_id) and (private.is_admin(organization_id) or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='finance'));
create policy finance_update on public.financial_transactions for update to authenticated using(private.can_access_branch(organization_id,branch_id) and private.is_admin(organization_id)) with check(private.can_access_branch(organization_id,branch_id) and private.is_admin(organization_id));
create policy finance_delete on public.financial_transactions for delete to authenticated using(private.is_admin(organization_id));
create policy audit_select on public.audit_events for select to authenticated using(private.can_access_branch(organization_id,branch_id) and private.is_admin(organization_id));
create policy audit_insert on public.audit_events for insert to authenticated with check(private.can_access_branch(organization_id,branch_id));
-- Authenticated role receives table access; RLS is the row-level gate.
grant select,insert,update,delete on all tables in schema public to authenticated;
grant usage,select on all sequences in schema public to authenticated;

-- Storage bucket for patient photos is private. Upload paths should be org/branch/patient/file.
insert into storage.buckets(id,name,public) values('clinic-patient-images','clinic-patient-images',false) on conflict(id) do nothing;
create policy clinic_images_read on storage.objects for select to authenticated using (bucket_id='clinic-patient-images' and private.can_access_branch((storage.foldername(name))[1]::uuid,(storage.foldername(name))[2]::uuid));
create policy clinic_images_upload on storage.objects for insert to authenticated with check (bucket_id='clinic-patient-images' and private.can_access_branch((storage.foldername(name))[1]::uuid,(storage.foldername(name))[2]::uuid));
create policy clinic_images_update on storage.objects for update to authenticated using (bucket_id='clinic-patient-images' and private.can_access_branch((storage.foldername(name))[1]::uuid,(storage.foldername(name))[2]::uuid)) with check (bucket_id='clinic-patient-images' and private.can_access_branch((storage.foldername(name))[1]::uuid,(storage.foldername(name))[2]::uuid));
create policy clinic_images_delete on storage.objects for delete to authenticated using (bucket_id='clinic-patient-images' and private.is_admin((storage.foldername(name))[1]::uuid));
